def compute(vars):
    high = vars["v1"]
    low = vars["v2"]
    average = (high + low) / 2
    return {
        "value": round(average, 3),
        "trace": {
            "high_price": high,
            "low_price": low,
            "average": average,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": "stock price"
            }
        }
    }
